'security_center.code_scan'=>array('label'=>$t('code_scan_label'),'description'=>$t('code_scan_description'),'default_cron'=>'*/2 * * * *','default_name'=>$t('code_scan_label'),'default_configuration'=>array('files_per_run'=>120),'managed_task'=>true,'callable'=>array('WbceSecurityCenterWorker','scan')),
