if(function_exists('wbce_add_action')){
 $log=static function($type,$severity='info',$details=array()){global $database;try{(new WbceSecurityCenterService($database))->event($type,$severity,$details);}catch(Throwable $e){error_log('WBCE Security Center event: '.$e->getMessage());}};
