 wbce_add_action('auth.login.succeeded',static function($userId)use($log){$log('auth.login.succeeded','info',array('user_id'=>(int)$userId));});
 wbce_add_action('auth.challenge.failed',static function($provider,$userId)use($log){$log('auth.factor.failed','warning',array('provider'=>(string)$provider,'user_id'=>(int)$userId));});
 foreach(array('addon.installed'=>'info','addon.upgraded'=>'info','addon.uninstalled'=>'warning')as$event=>$severity)wbce_add_action($event,static function($context)use($log,$event,$severity){if($event==='addon.uninstalled'&&($context['directory']??'')==='security_center')return;$log($event,$severity,(array)$context);});
 wbce_add_filter('admin.dashboard.widgets',static function($widgets){global $database;$summary=(new WbceSecurityCenterService($database))->summary();if($summary['critical']>0){$title=htmlspecialchars(WbceSecurityCenterLanguage::text('module.name','Security Center'),ENT_QUOTES,'UTF-8');$url=htmlspecialchars(ADMIN_URL.'/admintools/tool.php?tool=security_center&sc_page=scanner',ENT_QUOTES,'UTF-8');$content='<a class="security-center-dashboard-findings" href="'.$url.'"><strong>'.(int)$summary['critical'].'</strong> '.htmlspecialchars(WbceSecurityCenterLanguage::text('summary.dashboard_critical','critical or high-priority open findings.'),ENT_QUOTES,'UTF-8').'</a>';$widgets[]=array('html'=>'<section id="security-center-dashboard-widget" class="wbce-dashboard-hook-widget wbce-card"><h3><a href="'.$url.'">'.$title.'</a></h3><div class="wbce-dashboard-hook-content">'.$content.'</div></section><style>#security-center-dashboard-widget{grid-column:1/-1;box-sizing:border-box;width:100%;margin:0 0 1rem;padding:1rem 1.2rem;border:1px solid var(--wbce-admin-border,#dfe5e9);border-left:5px solid var(--wbce-admin-primary,#2271b1);border-radius:var(--wbce-admin-radius,0);background:var(--wbce-admin-surface,#fff);color:var(--wbce-admin-text,inherit);box-shadow:var(--wbce-admin-shadow,none)}#security-center-dashboard-widget h3{margin:0 0 .4rem}#security-center-dashboard-widget h3 a{color:#1769aa!important;text-decoration:none}#security-center-dashboard-widget h3 a:hover{text-decoration:underline}#security-center-dashboard-widget .wbce-dashboard-hook-content{line-height:1.45}#security-center-dashboard-widget .security-center-dashboard-findings{display:inline-block;color:#1769aa!important;font-weight:600;text-decoration:underline;text-underline-offset:.16em}#security-center-dashboard-widget .security-center-dashboard-findings:hover{text-decoration-thickness:2px}#security-center-dashboard-widget .security-center-dashboard-findings:focus-visible{outline:2px solid var(--wbce-admin-primary,#2271b1);outline-offset:3px}</style><script>(function(){var widget=document.getElementById("security-center-dashboard-widget"),shell=document.querySelector(".wbce-dashboard-shell"),grid=shell&&shell.querySelector(".wbce-dashboard-grid");if(widget&&grid)grid.insertBefore(widget,grid.firstChild);})();</script>','priority'=>15);}return $widgets;});
